```json
{
  "version": 1,
  "taskId": "64e61d47-08d0-4d92-9f14-491fc2a736fd",
  "commandId": "write-4",
  "operation": "run",
  "headSha": "a4bf6e68d1ec87f6ea1faaf321505c380d437763",
  "timeoutSeconds": 120,
  "command": "cat > apps/mobile/src/components/Composer.tsx <<'EOF'
import { useState } from 'react';
import {
  View,
  TextInput,
  Pressable,
  Text,
  StyleSheet,
} from 'react-native';
import { theme } from '../theme';
import { HoldToRecordButton } from './HoldToRecordButton';
import type { ChatMessage } from './MessageBubble';

type ComposerProps = {
  chatId: string;
  onSent: (msg: ChatMessage) => void;
  onSendText: (text: string) => Promise<void> | void;
};

export function Composer({ chatId, onSent, onSendText }: ComposerProps) {
  const [text, setText] = useState('');
  const [sending, setSending] = useState(false);
  const canSend = text.trim().length > 0;

  const handleSend = async () => {
    const value = text.trim();
    if (!value || sending) {
      return;
    }
    setSending(true);
    try {
      await onSendText(value);
      setText('');
    } finally {
      setSending(false);
    }
  };

  return (
    <View style={styles.wrap}>
      <TextInput
        style={styles.input}
        value={text}
        onChangeText={setText}
        placeholder="Сообщение"
        placeholderTextColor={theme.colors.muted}
        multiline
        editable={!sending}
      />
      {canSend ? (
        <Pressable
          accessibilityLabel="Отправить"
          accessibilityRole="button"
          disabled={sending}
          onPress={() => {
            void handleSend();
          }}
          style={({ pressed }) => [
            styles.sendBtn,
            pressed || sending ? styles.sendBtnPressed : null,
          ]}
        >
          <Text style={styles.sendIcon}>➤</Text>
        </Pressable>
      ) : (
        <HoldToRecordButton chatId={chatId} onSent={onSent} />
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: {
    flexDirection: 'row',
    alignItems: 'flex-end',
    paddingHorizontal: theme.spacing.sm,
    paddingVertical: theme.spacing.sm,
    backgroundColor: theme.colors.bar,
    borderTopWidth: StyleSheet.hairlineWidth,
    borderTopColor: theme.colors.hairline,
    gap: theme.spacing.sm,
  },
  input: {
    flex: 1,
    minHeight: 40,
    maxHeight: 120,
    paddingHorizontal: theme.spacing.md,
    paddingVertical: theme.spacing.sm,
    borderRadius: 20,
    backgroundColor: theme.colors.surface,
    color: theme.colors.text,
    fontSize: theme.typography.body.fontSize,
  },
  sendBtn: {
    width: 40,
    height: 40,
    borderRadius: 20,
    backgroundColor: theme.colors.accent,
    alignItems: 'center',
    justifyContent: 'center',
  },
  sendBtnPressed: {
    opacity: 0.7,
  },
  sendIcon: {
    color: theme.colors.text,
    fontSize: 18,
    marginLeft: 2,
  },
});
EOF"
}
```

